    '"""Full-screen clock for the PyS60 1.3.1 script shell."""\n'
    '\n'
    'import appuifw\n'
    'import e32\n'
    'import graphics\n'
    'import imp\n'
    'import os\n'
    'import sys\n'
    'from time import localtime\n'
    '\n'
    'from hub.dashboard import COLON_REGION, HEIGHT, WIDTH, draw_colon, render\n'
    '\n'
    '\n'
    'def keep_awake_callback(helper):\n'
    '    reset = getattr(e32, "reset_inactivity", None)\n'
    '    if reset is not None:\n'
    '        return reset\n'
    '\n'
    '    # PyS60 1.3.1 lacks the API. Cache the bundled EKA1 extension on the\n'
    '    # Python drive, or in phone memory if the MMC is read-only.\n'
    '    directory = os.path.dirname(appuifw.app.full_name())\n'
    '    paths = (os.path.join(directory, "_ngageawake_v1.pyd"),\n'
    '             u"c:\\\\system\\\\_ngageawake_v1.pyd")\n'
    '    for path in paths:\n'
    '        try:\n'
    '            try:\n'
    '                source = open(path, "rb")\n'
    '            except IOError:\n'
    '                source = open(path, "wb")\n'
    '                try:\n'
    '                    source.write(helper)\n'
    '                finally:\n'
    '                    source.close()\n'
    '            else:\n'
    '                try:\n'
    '                    if source.read(len(helper) + 1) != helper:\n'
    '                        continue\n'
    '                finally:\n'
    '                    source.close()\n'
    '            return imp.load_dynamic("_ngageawake", path).reset\n'
    '        except (IOError, OSError, ImportError):\n'
    '            continue\n'
    '    return None\n'
    '\n'
    '\n'
    'class PhoneClock:\n'
    '    def __init__(self, reset_inactivity):\n'
    '        self.image = graphics.Image.new((WIDTH, HEIGHT))\n'
    '        x, y, width, height = COLON_REGION\n'
    '        self.colon_background = graphics.Image.new((width, height))\n'
    '        self.colon_source = ((x, y), (x + width, y + height))\n'
    '        self.canvas = None\n'
    '        self.minute = None\n'
    '        self.second = None\n'
    '        self.lock = e32.Ao_lock()\n'
    '        self.timer = e32.Ao_timer()\n'
    '        self.error = None\n'
    '        self.reset_inactivity = reset_inactivity\n'
    '        self.running = False\n'
    '\n'
    '    def fill_rect(self, x, y, width, height, color):\n'
    '        self.image.rectangle((x, y, x + width, y + height), outline=None, fill=color)\n'
    '\n'
    '    def redraw(self, rect):\n'
    '        if self.canvas is not None and self.minute is not None:\n'
    '            size = self.canvas.size\n'
    '            if size == (WIDTH, HEIGHT):\n'
    '                self.canvas.blit(self.image)\n'
    '            else:\n'
    '                self.canvas.blit(self.image, target=((0, 0), size), scale=1)\n'
    '\n'
    '    def refresh(self):\n'
    '        now = localtime()\n'
    '        minute = now[:5]\n'
    '        if self.minute == minute and self.second == now[5]:\n'
    '            return\n'
    '        x, y, width, height = COLON_REGION\n'
    '        new_minute = self.minute != minute\n'
    '        if new_minute:\n'
    '            self.ink, self.shadow = render(self, now, animate_colon=False)\n'
    '            self.colon_background.blit(self.image, source=self.colon_source)\n'
    '        self.minute, self.second = minute, now[5]\n'
    '        if self.second % 2 == 0:\n'
    '            draw_colon(self, self.ink, self.shadow)\n'
    '        else:\n'
    '            self.image.blit(self.colon_background, target=(x, y))\n'
    '        if new_minute or self.canvas.size != (WIDTH, HEIGHT):\n'
    '            self.redraw(None)\n'
    '        else:\n'
    '            self.canvas.blit(self.image, target=(x, y), source=self.colon_source)\n'
    '\n'
    '    def tick(self):\n'
    '        if not self.running:\n'
    '            return\n'
    '        try:\n'
    '            if self.reset_inactivity is not None:\n'
    '                self.reset_inactivity()\n'
    '            self.refresh()\n'
    '            self.timer.after(1, self.tick)\n'
    '        except Exception:\n'
    '            self.error = sys.exc_info()[1]\n'
    '            self.stop()\n'
    '\n'
    '    def stop(self):\n'
    '        if self.running:\n'
    '            self.running = False\n'
    '            self.timer.cancel()\n'
    '            self.lock.signal()\n'
    '\n'
    '    def run(self):\n'
    '        app = appuifw.app\n'
    '        previous_screen = app.screen\n'
    '        previous_body = app.body\n'
    '        previous_exit = app.exit_key_handler\n'
    '        try:\n'
    '            if self.reset_inactivity is None:\n'
    '                appuifw.note(u"The clock can run, but keep-awake is unavailable.", "info")\n'
    '            app.screen = "full"\n'
    '            self.canvas = appuifw.Canvas(redraw_callback=self.redraw)\n'
    '            app.body = self.canvas\n'
    '            app.exit_key_handler = self.stop\n'
    '            self.running = True\n'
    '            self.tick()\n'
    '            self.lock.wait()\n'
    '            if self.error is not None:\n'
    '                raise self.error\n'
    '        finally:\n'
    '            self.running = False\n'
    '            self.timer.cancel()\n'
    '            self.canvas = None\n'
    '            app.body = previous_body\n'
    '            app.screen = previous_screen\n'
    '            app.exit_key_handler = previous_exit\n'
    '\n'
    '\n'
    'def main(helper):\n'
    '    PhoneClock(keep_awake_callback(helper)).run()\n'
